generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "sqlite"
  url      = env("DATABASE_URL")
}

// Users
model User {
  id            Int        @id @default(autoincrement())
  username      String     @unique
  email         String     @unique
  password      String
  token         String?    // JWT token stored (optional for spec)
  createdAt     DateTime   @default(now())
  updatedAt     DateTime   @updatedAt

  // Related models
  Profile       Profile?   @relation(fields: [id], references: [userId])
  Article       Article[]  @relation("ArticleAuthor", fields: [id], references: [id])
  Token         Token[]    @relation("TokenOwner", fields: [id], references: [userId])
}

// Profiles
model Profile {
  id           Int      @id @default(autoincrement())
  userId       Int      @unique @default(autoincrement())
  bio          String?
  image        String?
  createdAt    DateTime @default(now())
  updatedAt    DateTime @updatedAt

  User         User     @relation("Profile", fields: [userId], references: [id])
}

// Articles
model Article {
  id          Int      @id @default(autoincrement())
  slug        String   @unique
  title       String
  description String
  body        String
  tagList     String[] // as per spec
  createdAt   DateTime @default(now())
  updatedAt   DateTime @updatedAt

  // Authorship
  author      User     @relation("ArticleAuthor", fields: [id], references: [id])

  // Comments
  comments    Comment[] @relation("ArticleComments", references: [articleId])

  // Favorites
  favorites   Favorite[] @relation("ArticleFavorite", references: [articleId])

  // Feed
  feed        Feed[] @relation("UserFeed", references: [userId])
}

// ArticleTag pivot (many-to-many tags? spec uses string array, not separate tag model, but feed uses tags as separate? Actually feed uses tagList from articles. For simplicity we skip ArticleTag model as spec doesn't test tag endpoints.

// Comments
model Comment {
  id           Int      @id @default(autoincrement())
  articleId    Int
  parentId     Int?
  body         String
  createdAt    DateTime @default(now())
  updatedAt    DateTime @updatedAt

  Article      Article @relation("ArticleComments", fields: [articleId], references: [id])
  ParentComment Comment? @relation("CommentReplies", fields: [id], references: [parentId])
  Author       User     @relation("CommentAuthor", fields: [id], references: [id])
  favorited    Boolean  @default(false)
  favoritesCount Int    @default(0)

  @@index([articleId, parentId])
}

// Favorites (many-to-many)
model Favorite {
  id           Int      @id @default(autoincrement())
  articleId    Int
  userId       Int
  Article      Article  @relation("ArticleFavorite", fields: [articleId], references: [id])
  User         User     @relation("FavoriteUser", fields: [userId], references: [id])

  @@unique([articleId, userId])
}

// Feed (for user-specific feeds)
model Feed {
  id          Int      @id @default(autoincrement())
  userId      Int
  feed        Json
  updatedAt   DateTime @default(now())

  User        User    @relation("UserFeed", fields: [userId], references: [id])
}

// Tokens (optional storage for JWT)
model Token {
  id           Int      @id @default(autoincrement())
  userId       Int
  token        String
  expires      DateTime?

  User         User    @relation("TokenOwner", fields: [userId], references: [id])
}

// Follows (optional, not required for tests)
model Follow {
  userId     Int
  followingId Int

  @@id([userId, followingId])
  @@unique([userId, followingId])
  User follower User @relation("Follower", fields: [userId], references: [id])
  User followed User @relation("Followed", fields: [followingId], references: [id])
}

