import Fastify from "fastify";
import { PrismaClient } from "@prisma/client";
import dotenv from "dotenv";
import bcrypt from "bcrypt";
import jwt from "jsonwebtoken";
import { slugify } from "slugify";

dotenv.config();

const fastify = Fastify({
  logger: true,
});

const prisma = new PrismaClient();

const JWT_SECRET = process.env.JWT_SECRET ?? "supersecretkeychangeinproduction";

fastify.register(require("fastify-jwt"), {
  secret: JWT_SECRET,
});

// ---------- Error handler ----------
fastify.setErrorHandler((error, request, reply) => {
  // Map Prisma errors to API error format
  if (reply.statusCode === 404) {
    reply.send({
      error: "Not found",
      message: "The requested resource could not be found.",
    });
  } else {
    reply.send({
      error: error.message,
      message: error.message,
    });
  }
});

// ---------- Health endpoint ----------
fastify.get("/health", async (_, reply) => {
  return { status: "ok" };
});

// ---------- Auth ----------
fastify.post("/api/users", async (request, reply) => {
  const { user } = request.body as { user: { username: string; email: string; password: string } };

  // Check if user already exists
  const existing = await prisma.user.findUnique({
    where: { username: user.username },
  });
  if (existing) {
    reply.code(400).send({
      error: "Validation Error",
      message: "Username already exists",
    });
    return;
  }

  // Hash password
  const hashed = await bcrypt.hash(user.password, 10);

  // Create user
  const created = await prisma.user.create({
    data: {
      username: user.username,
      email: user.email,
      password: hashed,
    },
  });

  // Generate JWT token (expires in 1 hour)
  const token = jwt.sign(
    { userId: created.id },
    JWT_SECRET,
    { expiresIn: "1h" },
  );

  reply.code(201).send({
    user: {
      id: created.id,
      username: created.username,
      email: created.email,
      token,
      bio: null,
      image: null,
    },
  });
});

// ---------- Login ----------
fastify.post("/api/users/login", async (request, reply) => {
  const { user } = request.body as { user: { email: string; password: string } };

  // Find user by email
  const userRecord = await prisma.user.findUnique({
    where: { email: user.user.email },
  });
  if (!userRecord || !(await bcrypt.compare(user.user.password, userRecord.password))) {
    reply.code(401).send({
      error: "Not authorized",
      message: "Invalid email or password",
    });
    return;
  }

  // Generate JWT token
  const token = jwt.sign(
    { userId: userRecord.id },
    JWT_SECRET,
    { expiresIn: "1h" },
  );

  reply.code(200).send({
    user: {
      username: userRecord.username,
      email: userRecord.email,
      bio: userRecord.bio,
      image: userRecord.image,
      token,
    },
  });
});

// ---------- Current user ----------
fastify.get("/api/user", async (request, reply) => {
  const userId = request.user.userId;
  const user = await prisma.user.findUnique({
    where: { id: userId },
  });
  if (!user) {
    reply.code(404).send({
      error: "User not found",
      message: "The requested user does not exist.",
    });
    return;
  }

  reply.send({
    user: {
      id: user.id,
      username: user.username,
      email: user.email,
      bio: user.bio,
      image: user.image,
    },
  });
});

// ---------- Update user ----------
fastify.put("/api/user", async (request, reply) => {
  const userId = request.user.userId;
  const { user } = request.body as { user: { bio?: string; image?: string } };

  const updated = await prisma.user.update({
    where: { id: userId },
    data: {
      bio: user.bio ?? null,
      image: user.image ?? null,
    },
  });

  // Normalize null for empty string
  if (typeof updated.bio === "string" && updated.bio === "") updated.bio = null;
  if (typeof updated.image === "string" && updated.image === "") updated.image = null;
  if (typeof updated.bio === "null" && updated.bio !== null) updated.bio = null;
  if (typeof updated.image === "null" && updated.image !== null) updated.image = null;

  reply.send({
    user: {
      id: updated.id,
      username: updated.username,
      email: updated.email,
      bio: updated.bio,
      image: updated.image,
      token: request.user.token,
    },
  });
});

// ---------- Follow profile ----------
fastify.post("/api/profiles/:username/follow", async (request, reply) => {
  const userId = request.user.userId;
  const username = request.params.username;

  // Verify that the target profile belongs to a valid user
  const targetUser = await prisma.user.findUnique({
    where: { username },
  });
  if (!targetUser) {
    reply.code(404).send({
      error: "Profile not found",
      message: `Profile with username '${username}' does not exist.`,
    });
    return;
  }

  // Create follow relationship (inverse relationship)
  await prisma.follow.create({
    data: {
      followerId: userId,
      followingId: targetUser.id,
    },
  });

  reply.code(200).send({
    profile: {
      userId: targetUser.id,
      bio: targetUser.bio,
      image: targetUser.image,
      following: true,
    },
  });
});

// ---------- Unfollow profile ----------
fastify.delete("/api/profiles/:username/follow", async (request, reply) => {
  const userId = request.user.userId;
  const username = request.params.username;

  const targetUser = await prisma.user.findUnique({
    where: { username },
  });
  if (!targetUser) {
    reply.code(404).send({
      error: "Profile not found",
      message: `Profile with username '${username}' does not exist.`,
    });
    return;
  }

  // Delete follow relationship
  await prisma.follow.delete({
    where: { followerId: userId, followingId: targetUser.id },
  });

  reply.code(200).send({
    profile: {
      userId: targetUser.id,
      bio: targetUser.bio,
      image: targetUser.image,
      following: false,
    },
  });
});

// ---------- Create article ----------
fastify.post("/api/articles", async (request, reply) => {
  const userId = request.user.userId;
  const { article } = request.body as { article: { title: string; description: string; body: string; tagList?: string[] } };

  const created = await prisma.article.create({
    data: {
      title: article.title,
      description: article.description,
      body: article.body,
      tagList: article.tagList ?? [],
      author: {
        connect: { id: userId },
      },
    },
  });

  reply.code(201).send({
    article: {
      slug: created.slug,
      title: created.title,
      description: created.description,
      body: created.body,
      tagList: created.tagList,
      createdAt: created.createdAt,
      updatedAt: created.updatedAt,
    },
  });
});

// ---------- List articles by author ----------
fastify.get("/api/articles", async (request, reply) => {
  const userId = request.user.userId;
  const authorUsername = request.query.author;
  let authorId;
  if (authorUsername) {
    authorId = await prisma.user.findUnique({
      where: { username: authorUsername },
    })?.id;
    if (!authorId) {
      reply.code(404).send({
        error: "Not found",
        message: `No articles found for author '${authorUsername}'.`,
      });
      return;
    }
  } else {
    authorId = userId;
  }

  const articles = await prisma.article.findMany({
    where: {
      author: { id: authorId },
    },
    orderBy: { createdAt: "desc" },
  });

  const response = articles.map((a) => ({
    slug: a.slug,
    title: a.title,
    description: a.description,
    body: a.body,
    tagList: a.tagList,
    createdAt: a.createdAt,
    updatedAt: a.updatedAt,
    favorited: false, // not stored in DB
  }));

  reply.send({
    articles: response,
  });
});

// ---------- List articles by tag ----------
fastify.get("/api/articles/:slug", async (request, reply) => {
  const { slug } = request.params;
  const articles = await prisma.article.findMany({
    where: { tagList: { has: slug } },
    orderBy: { createdAt: "desc" },
  });

  const response = articles.map((a) => ({
    slug: a.slug,
    title: a.title,
    description: a.description,
    body: a.body,
    tagList: a.tagList,
    createdAt: a.createdAt,
    updatedAt: a.updatedAt,
    favorited: false,
  }));

  // Spec expects error if slug not found? Actually spec expects 404 if no article with that slug.
  if (response.length === 0) {
    reply.code(404).send({
      error: "Not found",
      message: `No article found with tag '${slug}'.`,
    });
    return;
  }

  reply.send({
    articles: response,
  });
});

// ---------- Get single article ----------
fastify.get("/api/articles/:slug", async (request, reply) => {
  const { slug } = request.params;
  const article = await prisma.article.findUnique({
    where: { slug },
  });
  if (!article) {
    reply.code(404).send({
      error: "Not found",
      message: `Article with slug '${slug}' does not exist.`,
    });
    return;
  }

  reply.send({
    article: {
      slug: article.slug,
      title: article.title,
      description: article.description,
      body: article.body,
      tagList: article.tagList,
      createdAt: article.createdAt,
      updatedAt: article.updatedAt,
      favorited: false,
    },
  });
});

// ---------- Delete article ----------
fastify.delete("/api/articles/:slug", async (request, reply) => {
  const userId = request.user.userId;
  const { slug } = request.params;
  const article = await prisma.article.findUnique({
    where: { slug },
  });
  if (!article) {
    reply.code(404).send({
      error: "Not found",
      message: `Article with slug '${slug}' does not exist.`,
    });
    return;
  }

  // Author must own the article
  if (article.authorId !== userId) {
    reply.code(403).send({
      error: "Forbidden",
      message: "You are not authorized to delete this article.",
    });
    return;
  }

  await prisma.article.delete({
    where: { slug },
  });

  reply.code(200).send({});
});

// ---------- Update article ----------
fastify.put("/api/articles/:slug", async (request, reply) => {
  const userId = request.user.userId;
  const { slug } = request.params;
  const { article } = request.body as { article: { title?: string; description?: string; body?: string; tagList?: string[] } };

  const existing = await prisma.article.findUnique({
    where: { slug },
  });
  if (!existing) {
    reply.code(404).send({
      error: "Not found",
      message: `Article with slug '${slug}' does not exist.`,
    });
    return;
  }

  // Author must be the article author
  if (existing.authorId !== userId) {
    reply.code(403).send({
      error: "Forbidden",
      message: "You are not authorized to edit this article.",
    });
    return;
  }

  const updated = await prisma.article.update({
    where: { slug },
    data: {
      title: article.title ?? existing.title,
      description: article.description ?? existing.description,
      body: article.body ?? existing.body,
      tagList: article.tagList ?? existing.tagList,
      updatedAt: new Date(), // auto via @updatedAt
    },
  });

  // Normalize null for empty strings
  if (typeof updated.tagList === "string[]" && updated.tagList.length > 0 && updated.tagList[0] === "") {
    // if empty string in array, replace with null
    updated.tagList = updated.tagList.map((t) => (t === "" ? null : t));
  }
  if (typeof updated.tagList === "null" && updated.tagList !== null) {
    // if null values, replace with empty string? Actually spec expects null for empty string normalization.
    // Keep as null.
  }

  reply.send({
    article: {
      slug: updated.slug,
      title: updated.title,
      description: updated.description,
      body: updated.body,
      tagList: updated.tagList,
      createdAt: updated.createdAt,
      updatedAt: updated.updatedAt,
    },
  });
});

// ---------- Favorite article ----------
fastify.post("/api/articles/:slug/favorite", async (request, reply) => {
  const userId = request.user.userId;
  const { slug } = request.params;

  const article = await prisma.article.findUnique({
    where: { slug },
  });
  if (!article) {
    reply.code(404).send({
      error: "Article not found",
      message: `Article with slug '${slug}' does not exist.`,
    });
    return;
  }

  // Check if already favorited
  const existing = await prisma.favorite.findUnique({
    where: { articleId: article.id, userId },
  });
  if (existing) {
    reply.code(409).send({
      error: "Already favorited",
      message: `Article is already favorited by this user.`,
    });
    return;
  }

  await prisma.favorite.create({
    data: {
      articleId: article.id,
      userId,
    },
  });

  reply.code(201).send({});
});

// ---------- Unfavorite article ----------
fastify.delete("/api/articles/:slug/favorite", async (request, reply) => {
  const userId = request.user.userId;
  const { slug } = request.params;

  const article = await prisma.article.findUnique({
    where: { slug },
  });
  if (!article) {
    reply.code(404).send({
      error: "Article not found",
      message: `Article with slug '${slug}' does not exist.`,
    });
    return;
  }

  // Delete favorite relationship
  await prisma.favorite.delete({
    where: { articleId: article.id, userId },
  });

  reply.code(200).send({});
});

// ---------- Feed ----------
fastify.get("/api/feed", async (request, reply) => {
  const userId = request.user.userId;
  // For simplicity, feed returns articles by authors the user follows.
  // In spec, feed returns articles sorted by updatedAt.
  // We'll compute followers list via Follow model.
  const feeds = await prisma.feed.findMany({
    where: { userId },
    orderBy: { updatedAt: "desc" },
  });

  // Each feed entry is a JSON object with userId and feed.
  const response = feeds.map((f) => ({
    userId: f.userId,
    feed: f.feed,
  }));

  reply.send({
    profiles: response,
  });
});

// ---------- Tags ----------
fastify.get("/api/tags", async (request, reply) => {
  const tags = await prisma.article.findMany({
    distinct: true,
    select: { tagList: true },
  }).then((articles) => articles.flatMap((a) => a.tagList)).filter((t): t is string => typeof t === "string");

  // Deduplicate and sort
  const distinctTags = [...new Set(tags)].sort();

  reply.send({
    tags: distinctTags,
  });
});

fastify.listen({ port: 8000 }, (err, address) => {
  if (err) {
    fastify.log.error(err);
    process.exit(1);
  }
  fastify.log.info(`Server is running at ${address}`);
});

