// ---------- Update profile ----------
fastify.put("/api/profiles/:username/update", async (request, reply) => {
  const username = request.params.username;
  const userId = request.user.userId;
  const { profile } = request.body as { profile: { bio?: string; image?: string } };

  const target = await prisma.user.findUnique({ where: { username } });
  if (!target) {
    reply.code(404).send({
      error: "Profile not found",
      message: `Profile with username '${username}' does not exist.`,
    });
    return;
  }

  // Only allow updating own profile (authorization)
  if (username !== request.user.userId && userId !== target.id) {
    reply.code(403).send({
      error: "Forbidden",
      message: "You are not authorized to update this profile.",
    });
    return;
  }

  const updated = await prisma.user.update({
    where: { id: target.id },
    data: {
      bio: profile.bio ?? null,
      image: profile.image ?? null,
    },
  });

  // Normalize null for empty string
  if (typeof updated.bio === "string" && updated.bio === "") updated.bio = null;
  if (typeof updated.image === "string" && updated.image === "") updated.image = null;
  if (typeof updated.bio === "null" && updated.bio !== null) updated.bio = null;
  if (typeof updated.image === "null" && updated.image !== null) updated.image = null;

  reply.send({
    profile: {
      userId: target.id,
      username: target.username,
      bio: updated.bio,
      image: updated.image,
    },
  });
});

