// ---------- Update auth ----------
fastify.put("/api/auth/:username/update", async (request, reply) => {
  const username = request.params.username;
  const { user } = request.body as { user: { bio?: string; image?: string; password?: string } };

  const target = await prisma.user.findUnique({ where: { username } });
  if (!target) {
    reply.code(404).send({
      error: "Profile not found",
      message: `Profile with username '${username}' does not exist.`,
    });
    return;
  }

  // Authorization: only authenticated user can update
  if (!request.user) {
    reply.code(401).send({
      error: "Not authorized",
      message: "Authentication required",
    });
    return;
  }

  if (username !== request.user.userId && request.user.userId !== target.id) {
    reply.code(403).send({
      error: "Forbidden",
      message: "You are not authorized to update this profile.",
    });
    return;
  }

  if (user.bio !== undefined) {
    await prisma.user.update({ where: { id: target.id }, data: { bio: user.bio ?? null } });
  }
  if (user.image !== undefined) {
    await prisma.user.update({ where: { id: target.id }, data: { image: user.image ?? null } });
  }
  if (user.password !== undefined) {
    const hashed = await bcrypt.hash(user.password, 10);
    await prisma.user.update({ where: { id: target.id }, data: { password: hashed } });
  }

  // Normalize null for empty strings
  if (typeof target.bio === "string" && target.bio === "") target.bio = null;
  if (typeof target.image === "string" && target.image === "") target.image = null;
  if (typeof target.bio === "null" && target.bio !== null) target.bio = null;
  if (typeof target.image === "null" && target.image !== null) target.image = null;

  reply.send({
    user: {
      id: target.id,
      username: target.username,
      bio: target.bio,
      image: target.image,
      token: request.user.token,
    },
  });
});

